/** Standalone jump/landing work–energy workspace. Load after Studio and analysis.
 * Inputs: saved project mm/deg/kg/N and optional energy/target metadata; outputs
 * instant equations, Plotly BASIC charts, samples and app-folder JSON/CSV.
 * No trajectory request is made. Explicit handoff copies a physical-side command
 * and navigates only; endpoint work is not tested dynamic or hardware capability.
 */
globalThis.KinefoldEnergyUI=(()=>{
  'use strict';
  const S=KinefoldStudio,P=KinefoldProjects,A=KinefoldEnergyAnalysis;
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=(v,n=4)=>Number.isFinite(v)?(Math.abs(v)<.5*10**(-n)?0:v).toLocaleString('en-CA',{maximumFractionDigits:n}):'Unassessed';
  const card=(label,value,unit)=>`<div class="readout"><span>${label}</span><strong>${fmt(value)}<small>${unit}</small></strong></div>`;
  const field=(attr,key,label,unit,min,max,step='any')=>`<label>${label} · ${unit}<input ${attr}="${key}" type="number" min="${min}" max="${max}" step="${step}"></label>`;
  let root,kind='landing',lastKey='',result=null,project=null,plotRange={heightMinMm:0,heightMaxMm:3000},chartKey='';
  const plotRanges={landing:plotRange,jump:{heightMinMm:0,heightMaxMm:3000}};
  let includeLegMasses=true;
  try{includeLegMasses=globalThis.localStorage?.getItem('kinefold-energy-leg-masses')!=='false';}catch{}
  let activeJumpBand=null;
  const calculationOptions=extra=>({...extra,includeLegMasses,jumpTravel:kind==='jump'});
  const energy=p=>({...P.energyDefaults,dropHeightMm:p.caseConfig?.landingDropMm??P.caseDefaults.landingDropMm,...p.energyConfig});
  function travelMarkup(){return `<section class="energy-travel-panel energy-input-card" data-energy-travel-panel><div class="energy-plot-heading"><div><h3 data-energy-travel-title>Landing travel limits</h3><p>Range inputs edit this Energy case. The full 90° action updates working mechanical stops; save the named design separately.</p></div><div class="design-actions"><button data-energy-full-travel>Use full 90° · update working stops</button><button data-energy-travel-reset>Restore case default</button></div></div><p class="notice" data-energy-travel-limit role="status"></p><div class="energy-travel-band" data-energy-travel-band><input type="range" min="0" max="1" step="any" data-energy-travel-range="min" aria-label="Minimum energy-case clearance"><input type="range" min="0" max="1" step="any" data-energy-travel-range="max" aria-label="Maximum energy-case clearance"></div><div class="energy-travel-values"><label>Minimum underside clearance · mm<input type="number" step="any" data-energy-travel-value="min"></label><label>Maximum underside clearance · mm<input type="number" step="any" data-energy-travel-value="max"></label></div><div class="energy-travel-values energy-travel-angles"><label>Compressed endpoint θ₂ · deg<input type="number" step="any" data-energy-travel-angle="compressed"></label><label>Extended endpoint θ₂ · deg<input type="number" step="any" data-energy-travel-angle="extended"></label></div><p class="notice warning" data-energy-travel-boundary hidden></p><div class="solver-readouts" data-energy-travel-metrics></div><details data-energy-travel-preview><summary>Minimum & maximum mechanism poses</summary><div class="energy-travel-poses" data-energy-travel-poses><article><h4>Minimum · compressed</h4><svg data-energy-travel-pose="min" role="img" aria-label="Compressed mechanism endpoint"></svg><p data-energy-travel-caption="min"></p></article><article><h4>Maximum · extended</h4><svg data-energy-travel-pose="max" role="img" aria-label="Extended mechanism endpoint"></svg><p data-energy-travel-caption="max"></p></article></div><p class="energy-travel-caption">Same scale and floor datum; +x left, +z up. Kinematic poses with wheel-drive input θ₄ held, not contact trajectories.</p></details></section>`;}
  function drawJumpPoses(p,band){
    const D=globalThis.KinefoldDrawing,d=band.undersideOffsetMm;
    const pose=q=>{const params={...p,theta2:q},z=Kinefold.evaluate(params);if(!z.valid)throw Error(z.errors.join(' '));const h=p.rw-z.C[2],W=v=>[v[0],v[1],v[2]+h],spring=D?.spring(params,{theta2:q,A:z.A,B:z.B,C:z.C});return {q,z,h,W,spring};};
    // Full allowed envelope keeps the camera scale unchanged while handles move.
    const qTop=p.te,qBottom=p.tc;
    const envelope=[pose(qTop),pose(qBottom)],points=envelope.flatMap(s=>[s.W(s.z.A),s.W(s.z.B),s.W([s.z.C[0]-p.rw,0,s.z.C[2]-p.rw]),s.W([s.z.C[0]+p.rw,0,s.z.C[2]+p.rw]),...(s.spring?.valid?[s.spring.D,s.spring.S,...s.spring.assemblyPoints].map(s.W):[])]);
    const xs=points.map(v=>-v[0]),center=(Math.min(...xs)+Math.max(...xs))/2,top=Math.max(...points.map(v=>v[2])),scale=Math.min(480/Math.max(250,Math.max(...xs)-Math.min(...xs)),300/Math.max(300,top)),floor=350;
    for(const [key,q]of [['min',band.qStartDeg],['max',band.qEndDeg]]){
      const s=pose(q),Pxy=v=>[300+(-v[0]-center)*scale,floor-v[2]*scale],local=v=>Pxy(s.W(v));
      const line=(a,b,color,width=1)=>{const[x,y]=local(a),[u,v]=local(b);return `<path d="M${x},${y}L${u},${v}" stroke="${color}" stroke-width="${width}" fill="none"/>`;};
      const grid=100*scale,gid='energy-travel-'+key+'-grid';let svg=`<defs><pattern id="${gid}" width="${grid}" height="${grid}" x="${300-center*scale}" y="${floor}" patternUnits="userSpaceOnUse"><path d="M${grid} 0H0V${grid}" fill="none" stroke="var(--line)" stroke-width=".7"/></pattern></defs><rect width="600" height="420" fill="var(--paper)"/><rect width="600" height="${floor}" fill="url(#${gid})"/><path d="M0 ${floor}H600" stroke="var(--sage)" stroke-width="2"/>`;
      svg+=line(s.z.A,s.z.B,'var(--sage)',10)+line(s.z.B,s.z.C,'var(--blue)',9);
      const [cx,cy]=local(s.z.C);svg+=`<circle cx="${cx}" cy="${cy}" r="${p.rw*scale}" fill="none" stroke="var(--ink)" stroke-width="2"/>`;
      if(D){for(const b of D.belts(s.z.reference,q))if(b.valid)svg+='<path d="'+b.outline.map((v,i)=>(i?'L':'M')+local(v).join(',')).join(' ')+'" fill="none" stroke="var(--muted)"/>';for(const a of D.indices(s.z.reference,q)){const[x,y]=local(a.center);svg+=`<circle cx="${x}" cy="${y}" r="${a.radius*scale}" fill="none" stroke="var(--amber)"/>`+line(a.center,a.primary,'var(--red)',1.2);}if(s.spring?.valid)svg+=D.springSvg(s.spring,local,scale);}
      const coincident=Math.hypot(...s.z.C.map((v,i)=>v-s.z.A[i]))<1e-7,labels=coincident?[[s.z.A,'A/C · hip / wheel'],[s.z.B,'B · knee']]:[[s.z.A,'A · hip'],[s.z.B,'B · knee'],[s.z.C,'C · wheel']];
      for(const [v,name]of labels){const[x,y]=local(v);svg+=`<circle cx="${x}" cy="${y}" r="3" fill="var(--paper)" stroke="var(--ink)"/><text x="${x+8}" y="${y-7}" font-size="11" fill="var(--ink)">${name}</text>`;}
      const [ux,uy]=Pxy([0,0,s.h-d]);svg+=`<path d="M${ux-18} ${uy}h36" stroke="var(--red)" stroke-dasharray="4 3"/><text x="${ux+23}" y="${uy+4}" font-size="9" fill="var(--red)">underside datum</text><text x="16" y="20" font-size="10" fill="var(--muted)">GRID 100 mm · SAME SCALE</text><path d="M90 390H30m7-4-7 4 7 4M90 390V368m-4 7 4-7 4 7" fill="none" stroke="var(--ink)"/><text x="9" y="393" font-size="10" fill="var(--red)">+x</text><text x="99" y="372" font-size="10" fill="var(--blue)">+z</text><text x="106" y="393" font-size="9" fill="var(--sage)">⊙ +y</text>`;
      const target=root.querySelector(`[data-energy-travel-pose="${key}"]`);target.setAttribute('viewBox','0 0 600 420');target.innerHTML=svg;
      root.querySelector(`[data-energy-travel-caption="${key}"]`).textContent=`θ₂ ${fmt(q,3)}° · underside clearance ${fmt(s.h-d,3)} mm · hip height ${fmt(s.h,3)} mm`;
    }
  }
  function renderJumpTravel(p){
    const panel=root.querySelector('[data-energy-travel-panel]');activeJumpBand=null;
    panel.querySelector('[data-energy-travel-title]').textContent=(kind==='jump'?'Jump launch':'Landing braking')+' travel limits';
    const controls=[...panel.querySelectorAll('[data-energy-travel-range]'),...panel.querySelectorAll('[data-energy-travel-value]')],angleControls=[...panel.querySelectorAll('[data-energy-travel-angle]')];
    try{
      const bounds=A.mechanicalTravel(p),lo=bounds.availableMinClearanceMm,hi=bounds.availableMaxClearanceMm;
      let band,error='';
      try{band=A.travelRange(p,kind);}catch(e){error=e.message;const saved=energy(p).travelRanges?.[kind];band={...bounds,...saved};}
      activeJumpBand=band;
      const min=band.minClearanceMm,max=band.maxClearanceMm;
      for(const el of angleControls){const q=el.dataset.energyTravelAngle==='compressed'?band.qStartDeg:band.qEndDeg;el.disabled=!Number.isFinite(q);el.min=p.params.te;el.max=p.params.tc;if(document.activeElement!==el)el.value=Number.isFinite(q)?q:'';}
      const boundary=panel.querySelector('[data-energy-travel-boundary]');boundary.hidden=!bounds.fullTravelBoundaryWarning;boundary.textContent=bounds.fullTravelBoundaryWarning||'';
      for(const el of controls){const key=el.dataset.energyTravelRange||el.dataset.energyTravelValue,value=key==='min'?min:max;el.disabled=!Number.isFinite(value);el.min=lo;el.max=hi;el.step='any';if(document.activeElement!==el)el.value=el.dataset.energyTravelValue&&Math.abs(value-Math.round(value))<1e-9?Math.round(value):value;el.setAttribute('aria-invalid',error?'true':'false');}
      panel.querySelector('[data-energy-travel-band]').setAttribute('style',`--band-min:${100*Math.max(0,Math.min(1,(min-lo)/(hi-lo)))}%;--band-max:${100*Math.max(0,Math.min(1,(max-lo)/(hi-lo)))}%`);
      panel.querySelector('[data-energy-travel-limit]').textContent=error||`${band.explicit?'Saved '+kind+' range':'Case default'}: ${fmt(min,3)}–${fmt(max,3)} mm. Mechanical envelope ${fmt(lo,3)}–${fmt(hi,3)} mm. ${kind==='landing'&&!band.explicit?'Default follows saved landing opening, residual clearance and angular reserve.':''}`;
      panel.querySelector('[data-energy-travel-limit]').className=error?'notice error':'notice';
      panel.querySelector('[data-energy-travel-metrics]').innerHTML=error?'':card('Vertical chassis travel',band.verticalTravelMm,'mm')+card('Hip rotation',band.angularTravelDeg,'°')+card('Travel along leg axis',band.legAxisTravelMm,'mm');
      panel.querySelector('[data-energy-travel-poses]').hidden=!!error;if(!error)drawJumpPoses(p.params,band);
    }catch(error){for(const el of [...controls,...angleControls])el.disabled=true;panel.querySelector('[data-energy-travel-limit]').textContent=error.message;panel.querySelector('[data-energy-travel-limit]').className='notice error';panel.querySelector('[data-energy-travel-metrics]').innerHTML='';panel.querySelector('[data-energy-travel-poses]').hidden=true;}
  }
  function editJumpRange(key,value,slider=false){
    edit(()=>{
      if(!activeJumpBand||!Number.isFinite(value))throw Error('Enter a finite clearance in mm.');
      const b=activeJumpBand,p=S.getSnapshot(),e=energy(p),range={minClearanceMm:b.minClearanceMm,maxClearanceMm:b.maxClearanceMm},gap=Math.min(.1,(b.availableMaxClearanceMm-b.availableMinClearanceMm)/10);
      if(slider)value=key==='min'?Math.max(b.availableMinClearanceMm,Math.min(range.maxClearanceMm-gap,value)):Math.min(b.availableMaxClearanceMm,Math.max(range.minClearanceMm+gap,value));
      range[key==='min'?'minClearanceMm':'maxClearanceMm']=value;
      const next={...e,travelRanges:{...e.travelRanges,[kind]:range}};
      P.validateEnergy(next);A.travelRange({...p,energyConfig:next},kind);S.setEnergyConfig(next);
    });
  }
  async function useFullTravel(){
    try{
      const next=A.fullTravelProject(S.exportProject(),kind),saved=await S.applySnapshot(next);
      if(saved===null)throw Error('Working-copy save failed; the previous design was restored.');
      lastKey='';update(S.getSnapshot(),true);S.toast('Working stops now span 90°; this Energy case uses full travel. Save the named design separately. Dynamic singularity guards remain active.');
    }catch(error){S.toast('Cannot use full travel: '+error.message);update(S.getSnapshot(),true);}
  }
  function editTravelAngle(){
    edit(()=>{const p=S.getSnapshot(),values=Object.fromEntries([...root.querySelectorAll('[data-energy-travel-angle]')].map(el=>[el.dataset.energyTravelAngle,el.value===''?NaN:Number(el.value)])),range=A.travelRangeFromAngles(p,kind,values.compressed,values.extended),e=energy(p);S.setEnergyConfig({...e,travelRanges:{...e.travelRanges,[kind]:range}});});
  }
  function table(head,rows,label){return `<div class="eqd-table-wrap"><table aria-label="${esc(label)}"><thead><tr>${head.map(s=>`<th>${esc(s)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(s=>`<td>${esc(s)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
  function mount(id='energy',host=document.getElementById('energy')){
    if(root)return;root=host;
    root.innerHTML=`<div class="solver-heading"><div><span class="eyebrow">WORK–ENERGY / INSTANT CALCULATOR</span><h2>Jump & landing energy</h2><p>Size constant torque, inspect every energy term and compare height targets. No simulation run is needed.</p></div><strong class="quarter-badge">¼ MODEL · SINGLE LEG</strong></div>
      <div class="energy-identity" data-energy-identity></div>
      <div class="energy-workspace"><aside class="energy-rail" aria-label="Energy modes and actions"><span class="eyebrow">ENERGY CASE</span><div class="energy-mode" role="group" aria-label="Energy case"><button data-energy-mode="jump" aria-pressed="false">Jump · rise above takeoff</button><button data-energy-mode="landing" aria-pressed="true">Landing · drop & arrest</button></div><button data-energy-principles>Principles · equations below</button><p>Instant endpoint-work screen. Detailed parameters and signed calculations follow the chart.</p><label class="energy-mass-toggle"><input type="checkbox" data-energy-leg-masses checked><span>Use saved leg masses</span></label><p data-energy-mass-note></p></aside><section class="energy-primary" data-energy-primary aria-label="Primary torque visualization"></section></div>
      <section class="energy-parameters" aria-label="Detailed energy parameters"><h3>Parameters &amp; saved settings</h3>${travelMarkup()}<details class="energy-input-card energy-saved-context"><summary><strong>Saved mechanism & mounting pitch</strong></summary><p data-energy-context-values></p><p class="notice" data-energy-alpha></p><button data-energy-alpha-edit>Edit α in Mechanism studio</button></details>
      <div class="energy-input-layout"><section class="energy-input-card"><h3 data-energy-input-heading></h3><div class="contact-controls"><div data-energy-for="jump">${field('data-energy-target','jumpHeightMm','Target chassis rise ABOVE TAKEOFF','mm',0,5000)}</div><div data-energy-for="landing">${field('data-energy-key','dropHeightMm','Drop H · initial wheel-bottom gap','mm',0,5000)}${field('data-energy-key','targetClearanceMm','Minimum residual UNDERBODY ground clearance','mm',0,5000)}${field('data-energy-key','compressionReserveDeg','Default stop reserve','deg',0,180)}</div><div>${field('data-energy-key','torqueLimitNm','Available constant HIP-JOINT torque · manual','N·m',0,10000)}</div></div><button data-energy-two-metre>2 m drop example</button><p data-energy-datum></p></section>
      <section class="energy-input-card"><h3 data-energy-geometry-heading>Shared saved landing geometry</h3><div class="contact-controls">${field('data-energy-case','landingOpenFraction','Landing opening fraction','0–1',.01,1,.01)}<label>Chassis underside BELOW HIP A · mm<input data-energy-case="undersideOffsetMm" type="number" min="0" max="5000" placeholder="Blank = clearance unassessed"></label></div><p>Opening changes the landing start pose. The underside offset converts hip height to ground clearance. These are shared case inputs; height targets and catalog screen are saved analysis metadata.</p><p data-energy-geometry-note></p><button data-energy-builder>Mechanism & saved designs</button></section></div>
      <details class="energy-catalog energy-input-card"><summary><strong>Optional motor & gearbox capacity · analysis candidate</strong></summary><div class="contact-controls"><label>Motor peak rating<select data-energy-motor><option value="manual">Manual joint torque · saved physical gearing</option><option value="custom">Custom motor peak</option>${A.motors.map(m=>`<option value="${m.id}">${esc(m.name)} · ${m.peakShaftNm} N·m</option>`).join('')}</select></label><label>Candidate reduction<select data-energy-gear><option value="direct">Direct drive · 1:1</option>${A.gearboxes.map(g=>`<option value="${g.id}">${g.name} · ${g.ratio}:1</option>`).join('')}<option value="custom">Custom reduction</option></select></label>${field('data-energy-screen','peakShaftNm','Peak MOTOR-SHAFT torque','N·m',0,10000)}${field('data-energy-screen','customRatio','Custom reduction N',':1',.000001,10000)}<label>Custom gearbox momentary OUTPUT limit · N·m<input data-energy-screen="customMomentaryNm" type="number" min="0" max="10000" placeholder="Blank = unassessed"></label></div><p>This candidate does not change the physical motor or either solver. Motor peak × N is capped separately by gearbox momentary output; nominal output is shown independently. No catalog inertia, friction or cogging is invented.</p></details>
      <section class="energy-input-card"><h3>Optional next step · test a command</h3><p data-energy-handoff></p><div class="design-actions"><button data-energy-settings>Open dynamic contact & motor settings</button><button data-energy-use="analytical">Use physical estimate in Analytical</button><button data-energy-use="pymunk">Use physical estimate in Pymunk</button></div><p>Copies a positive command magnitude in the saved physical motor’s command basis and opens that engine. The case controller applies negative generalized hip torque for extension/braking. It does not run a simulation or install the catalog motor.</p></section>
      <section class="energy-input-card"><h3>Source ratings & scope</h3><details><summary>All 9 motor variants and 4 gearbox ratings</summary><p>Catalog snapshot 23 Oct 2026. Maximum/peak shaft torque is not continuous or verified regenerative braking capability. Sale/used duplicates are removed.</p>${table(['Motor','Peak shaft · N·m','Duration'],A.motors.map(m=>[m.name,fmt(m.peakShaftNm),m.duration]),'Motor catalog')}${table(['Gearbox','Ratio N','Nominal output · N·m','Momentary output · N·m','Forward efficiency · reference only'],A.gearboxes.map(g=>[g.name,fmt(g.ratio),fmt(g.nominalNm),fmt(g.momentaryNm),fmt(g.forwardEfficiency*100)+'%']),'Gearbox catalog')}<p>Momentary duration, adapter/shaft fit and backdrive efficiency remain unverified. <a href="https://flipsky.net/collections/motor" target="_blank" rel="noreferrer">Flipsky motor family</a> · <a href="https://www.omc-stepperonline.com/nema-23-eg-series-planetary-gearbox" target="_blank" rel="noreferrer">EG gearbox family</a>.</p></details><button data-energy-remove>Remove saved energy-calculator metadata</button><p>Reset removes only energyConfig. Saved jump targets and shared landing geometry are retained.</p></section></section>
      <section class="energy-results" aria-label="Energy calculation and results"><p class="energy-announcement" data-energy-announcement role="status" aria-live="polite"></p><div data-energy-output></div></section>`;
    root.querySelector('[data-energy-leg-masses]').onchange=event=>{includeLegMasses=event.target.checked;try{globalThis.localStorage?.setItem('kinefold-energy-leg-masses',String(includeLegMasses));}catch{}lastKey='';update(S.getSnapshot(),true);};
    const clearance=root.querySelector('[data-energy-key="targetClearanceMm"]').closest('label');clearance.closest('.contact-controls').append(clearance);
    for(const el of root.querySelectorAll('[data-energy-travel-range]'))el.oninput=()=>editJumpRange(el.dataset.energyTravelRange,Number(el.value),true);
    for(const el of root.querySelectorAll('[data-energy-travel-value]'))el.onchange=()=>editJumpRange(el.dataset.energyTravelValue,el.value===''?NaN:Number(el.value));
    for(const el of root.querySelectorAll('[data-energy-travel-angle]'))el.onchange=editTravelAngle;
    root.querySelector('[data-energy-full-travel]').onclick=useFullTravel;
    root.querySelector('[data-energy-travel-reset]').onclick=()=>edit(()=>{const e=energy(S.getSnapshot()),ranges={...e.travelRanges};delete ranges[kind];if(Object.keys(ranges).length)e.travelRanges=ranges;else delete e.travelRanges;S.setEnergyConfig(e);});
    for(const b of root.querySelectorAll('[data-energy-mode]'))b.onclick=()=>open(b.dataset.energyMode);
    root.querySelector('[data-energy-principles]').onclick=()=>{const target=root.querySelector('[data-energy-equations]');if(target){target.scrollIntoView({block:'start'});target.focus({preventScroll:true});}else S.toast('Principles and equations are available after resolving the input error.');};
    root.querySelector('[data-energy-builder]').onclick=()=>S.showTab('builder');
    root.querySelector('[data-energy-alpha-edit]').onclick=()=>S.showTab('builder');
    root.querySelector('[data-energy-settings]').onclick=()=>S.showTab('pymunk');
    root.querySelector('[data-energy-two-metre]').onclick=()=>S.setEnergyConfig({...energy(S.getSnapshot()),dropHeightMm:2000});
    root.querySelector('[data-energy-remove]').onclick=()=>S.setEnergyConfig(null);
    for(const el of root.querySelectorAll('[data-energy-key]'))el.onchange=()=>edit(()=>S.setEnergyConfig({...energy(S.getSnapshot()),[el.dataset.energyKey]:el.value===''?NaN:Number(el.value)}));
    for(const el of root.querySelectorAll('[data-energy-target]'))el.onchange=()=>edit(()=>S.setTorqueTargetConfig({...P.torqueTargetDefaults,...S.getSnapshot().torqueTargetConfig,[el.dataset.energyTarget]:el.value===''?NaN:Number(el.value)}));
    for(const el of root.querySelectorAll('[data-energy-case]'))el.onchange=()=>edit(()=>S.setCaseConfig({...P.caseDefaults,...S.getSnapshot().caseConfig,[el.dataset.energyCase]:el.value===''?(el.dataset.energyCase==='undersideOffsetMm'?null:NaN):Number(el.value)}));
    for(const el of root.querySelectorAll('[data-energy-screen], [data-energy-motor], [data-energy-gear]'))el.onchange=()=>edit(()=>changeScreen(el));
    for(const b of root.querySelectorAll('[data-energy-use]'))b.onclick=()=>useEstimate(b.dataset.energyUse);
  }
  function edit(fn){try{fn();}catch(error){S.toast(error.message);update(S.getSnapshot(),true);}}
  function changeScreen(el){
    const e=energy(S.getSnapshot()),motorId=root.querySelector('[data-energy-motor]').value;
    if(motorId==='manual'){delete e.screening;}else{
      const selected=A.motors.find(m=>m.id===motorId),old=e.screening,fields=Object.fromEntries([...root.querySelectorAll('[data-energy-screen]')].map(f=>[f.dataset.energyScreen,f.value===''?null:Number(f.value)]));
      const peak=el.hasAttribute('data-energy-motor')?(selected?.peakShaftNm??old?.peakShaftNm??e.torqueLimitNm):(fields.peakShaftNm??selected?.peakShaftNm??e.torqueLimitNm);
      e.screening={motorId,gearboxId:root.querySelector('[data-energy-gear]').value,peakShaftNm:peak,customRatio:fields.customRatio??old?.customRatio??1,customMomentaryNm:fields.customMomentaryNm};
    }S.setEnergyConfig(e);
  }
  function open(next){if(!['jump','landing'].includes(next))return;plotRanges[kind]=plotRange;kind=next;plotRange=plotRanges[kind];lastKey='';update(S.getSnapshot());}
  function command(p,mode){
    const c={...P.caseDefaults,...p.caseConfig},e=energy(p),t={...P.torqueTargetDefaults,...p.torqueTargetConfig},m={...P.motorDefaults,...p.motorConfig};
    // A display-only massless approximation must never become a command for the
    // saved finite-mass mechanism. Recalculate with its actual masses here.
    const physicalOptions={includeLegMasses:true};
    const z=mode==='jump'?A.jumpEstimate(p,t.jumpHeightMm,physicalOptions):A.landingEstimate(p,e.dropHeightMm,e.targetClearanceMm,physicalOptions),joint=mode==='jump'?z.jointNm:z.requiredJointNm;
    const physicalRatio=m.enabled?KinefoldProjects.totalMotorRatio(m):1,basis=m.enabled&&m.commandBasis==='motor'?'motor':'joint',value=basis==='motor'?joint/physicalRatio:joint;
    const candidate={...p,caseConfig:{...c,kind:mode,brakeStrategy:'entered'}},reasons=[];
    if(e.travelRanges?.[mode])reasons.push('The selected '+mode+' travel is Energy-only. Dynamic cases do not yet replay custom Energy endpoints; restore the case default to copy a physical estimate.');
    if(!KinefoldContactUI.isContact(p))reasons.push('Select terrain-contact interaction in the dynamic tab before copying a jump/landing command.');
    reasons.push(...KinefoldContactUI.guards(candidate));
    try{const next={...c,kind:mode};if(mode==='jump')next.jumpTorqueNm=value;else{next.landingDropMm=e.dropHeightMm;next.landingBrakeTorqueNm=value;next.landingBrakeLimitNm=Math.max(c.landingBrakeLimitNm,value);next.brakeStrategy='entered';}P.validateCase(next);if(mode==='landing')P.validateTorqueTargets({...t,landingClearanceMm:e.targetClearanceMm});}
    catch(error){reasons.push('Command cannot be copied: '+error.message);}
    return {jointNm:joint,commandNm:value,basis,physicalRatio,brakeLimitNm:Math.max(c.landingBrakeLimitNm,value),reasons};
  }
  function handoff(){
    let info;
    try{info=command(project,kind);root.querySelector('[data-energy-handoff]').textContent=`Current PHYSICAL gearing N=${fmt(info.physicalRatio)}: ${fmt(info.jointNm)} joint N·m → ${fmt(info.commandNm)} ${info.basis}-side N·m. Recomputed with saved leg masses, physical gearing and passives, independently of the calculator mass approximation or catalog candidate. ${kind==='landing'?'Copying also sets the brake/search ceiling to '+fmt(info.brakeLimitNm)+' '+info.basis+' N·m so the command is not silently capped. ':''}${info.reasons.length?info.reasons.join(' '):'This is an untested endpoint-work estimate. Test both engines and inspect start/impact/stops and clearance.'}`;}
    catch(error){info={reasons:[error.message]};root.querySelector('[data-energy-handoff]').textContent='Simulation estimate unavailable: '+error.message;}

    for(const b of root.querySelectorAll('[data-energy-use]')){b.disabled=!result||info.reasons.length>0;b.textContent='Use physical estimate in '+(b.dataset.energyUse==='analytical'?'Analytical':'Pymunk');}
  }
  function useEstimate(engine){
    try{
      const p=S.getSnapshot(),info=command(p,kind);if(info.reasons.length)throw Error(info.reasons.join(' '));
      const c={...P.caseDefaults,...p.caseConfig};c.kind=kind;
      if(kind==='jump')c.jumpTorqueNm=info.commandNm;
      else{c.landingDropMm=energy(p).dropHeightMm;c.landingBrakeTorqueNm=info.commandNm;c.landingBrakeLimitNm=info.brakeLimitNm;c.brakeStrategy='entered';}
      P.validateCase(c);const nextTarget=kind==='landing'?P.validateTorqueTargets({...P.torqueTargetDefaults,...p.torqueTargetConfig,landingClearanceMm:energy(p).targetClearanceMm}):null;
      S.setCaseConfig(c);
      if(nextTarget)S.setTorqueTargetConfig(nextTarget);
      S.showTab(engine);S.toast(`Copied untested physical ${info.basis}-side estimate. Run or solve a target in ${engine}; no simulation was started.`);
    }catch(error){S.toast('Cannot copy estimate: '+error.message);update(S.getSnapshot(),true);}
  }
  function equations(z){
    const jump=z.kind==='jump',t=z.selectedHeightMm;
    const rows=[['Saved mounting pitch α','Fixed chassis mounting pitch, not terrain slope',z.alphaDeg,'°'],['Straight guide tilt from downward vertical','α − φ₀/2; + toward +x',z.guideTiltFromDownDeg,'°'],['Local geometry phase φ₀','Saved mechanism',z.phi0Deg,'°'],['Vertical source projection C_z','−sin(α) P_u(q) + cos(α) P_v(q)',z.stroke.at(-1).wheelCzMm,'mm'],['Horizontal source projection C_x','−cos(α) P_u(q) − sin(α) P_v(q)',z.endWheelCxMm,'mm'],['World wheel x at start','C_x(q₀, α), relative to fixed hip A',z.startWheelCxMm,'mm'],['Signed horizontal wheel travel','C_x(q₁, α) − C_x(q₀, α)',z.horizontalWheelTravelMm,'mm'],['Supported quarter chassis mass m₁','Saved mechanism',z.massKg,'kg'],['Gravity g','Saved mechanism',z.gravityMS2,'m/s²'],
      [jump?'Target rise H above takeoff':'Drop H before first contact','H_mm / 1000',t/1000,'m'],
      ['Hip start q₀',jump?'Selected compressed-start pose':'θ_c + opening × (θ_e − θ_c)',z.qStartDeg,'°'],['Hip endpoint q₁',jump?'Selected extended takeoff pose':'Clearance or mechanical compression endpoint',z.qEndDeg,'°'],
      ['Usable angular distance Δq','|q₁ − q₀| × π/180',z.angularTravelRad,'rad'],['Hip height at start h₀','r_w − C_z(q₀)',z.startHipHeightMm,'mm'],['Hip height at end h₁','r_w − C_z(q₁)',z.endHipHeightMm,'mm'],
      ['Underbody offset d below A','Shared landing geometry',z.undersideOffsetMm,'mm'],['Initial underbody clearance','h₀ − d',z.initialClearanceMm,'mm'],['Endpoint underbody clearance','h₁ − d',z.endClearanceMm,'mm']];
    if(jump)rows.push(['Wheel mass m₆','Saved mechanism · zero supported in this screen',z.wheelMassKg,'kg'],['Flight mass M','m₁ + included m₂ + m₃ + m₅ + m₆',z.flightMassKg,'kg'],['Stance chassis rise s','(h₁ − h₀)/1000',z.stanceRiseMm/1000,'m'],['Stance gravity increase ΔUg','Σmᵢg Δz_COM,i',z.stanceGravityJ,'J'],['Target airborne energy','M g H',z.flightEnergyJ,'J'],['Ideal takeoff speed','√(2gH)',z.targetTakeoffSpeedMS,'m/s'],['Ideal takeoff-to-apex time','√(2H/g)',Math.sqrt(2*t/1000/z.gravityMS2),'s'],['Spring energy released R_s','Us(q₀) − Us(q₁)',z.springReleaseJ,'J'],['Cogging energy released R_c','Uc(q₀) − Uc(q₁)',z.coggingReleaseJ,'J']);
    else rows.push(['Initial opening fraction','Saved landing case',z.openingFraction,'0–1'],['Chassis compression s','(h₀ − h₁)/1000',z.chassisCompressionMm/1000,'m'],['Impact speed','√(2gH)',z.impactSpeedMS,'m/s'],['Ideal pre-contact fall time','√(2H/g)',Math.sqrt(2*t/1000/z.gravityMS2),'s'],['Retained fall mass Mdrop','m₁ + included m₂ + m₃ + m₅',z.dropMassKg,'kg'],['Initial fall budget K₀','½Mdrop v² = Mdrop gH',z.dropJ,'J'],['Gravity released in compression','−Σmᵢg Δz_COM,i',z.gravityCompressionJ,'J'],['Spring energy stored ΔUs','Us(q₁) − Us(q₀)',-z.springReleasedJ,'J'],['Cogging energy stored ΔUc','Uc(q₁) − Uc(q₀)',-z.coggingReleasedJ,'J']);
    rows.push(['Included upper-link mass m₂',z.massModel,z.usedLinkMassesKg.upperLink,'kg'],['Included lower-link mass m₃',z.massModel,z.usedLinkMassesKg.lowerLink,'kg'],['Included compound-pulley mass m₅',z.massModel,z.usedLinkMassesKg.compound,'kg'],['Upper-link gravity change','m₂g Δz_COM,2',z.stroke.at(-1).upperLinkGravityDeltaJ,'J'],['Lower-link gravity change','m₃g Δz_COM,3',z.stroke.at(-1).lowerLinkGravityDeltaJ,'J'],['Compound-pulley gravity change','m₅g Δz_B',z.stroke.at(-1).compoundGravityDeltaJ,'J']);
    rows.push(['Signed endpoint motor work demand W',jump?'ΣmᵢgΔzᵢ + Mflight gH − R_s − R_c':'Mdrop gH − ΣmᵢgΔzᵢ − ΔUs − ΔUc',z.workJ,'J'],['Required constant JOINT magnitude τ','max(0, W / Δq)',z.requiredJointNm,'N·m'],['Analysis reduction N',z.screening?'Catalog candidate, physical motor unchanged':'Saved enabled physical gearing, else N=1',z.gearRatio,':1'],['Required constant SHAFT magnitude','τ_joint / N',z.requiredShaftNm,'N·m'],['Generalized JOINT command','−τ_joint; extension/braking on selected branch',z.generalizedJointCommandNm,'N·m'],['Motor work at endpoint','±τ_joint × Δq; + jump, − landing',z.stroke.at(-1).motorWorkJ,'J'],['Endpoint kinetic budget K_budget','K₀ + Wmotor − ΔUg − ΔUs − ΔUc',z.endpointKineticBudgetJ,'J'],['Minimum sampled kinetic budget','Signed values retained; no zero clipping',z.minKineticBudgetJ,'J']);
    return table(['Quantity / symbol','Equation / definition','Value','Unit'],rows.map(r=>[r[0],r[1],fmt(r[2],7),r[3]]),'Complete live energy calculation');
  }
  function screening(z){
    const s=z.screening;if(!s)return `<p>Manual available capacity: <b>${fmt(z.availableJointNm)} joint N·m</b>, ${fmt(z.availableShaftNm)} shaft N·m at saved physical N=${fmt(z.gearRatio)}. This is an entered constant-torque assumption.</p>`;
    return `<h4>${esc(s.motorName)} + ${esc(s.gearboxName)}</h4>${table(['Capacity quantity','Value','Meaning'],[
      ['Peak shaft rating',fmt(s.peakShaftNm)+' N·m',s.duration+(s.peakOverridden?' · catalog value overridden':'')],['Ideal motor joint peak',fmt(s.idealJointPeakNm)+' N·m','Peak shaft × N; ideal transmission'],['Gearbox nominal output',s.nominalNm===null?'Unassessed':fmt(s.nominalNm)+' N·m','Separate reference rating; not momentary'],['Gearbox momentary output',s.momentaryNm===null?(s.gearboxId==='direct'?'No gearbox':'Unassessed'):fmt(s.momentaryNm)+' N·m','Duration and braking capability unverified'],['Effective momentary screen',fmt(s.effectiveJointNm)+' joint N·m','min(motor ideal peak, known gearbox momentary limit)'],['Motor / gearbox comparison',(s.motorPass?'Motor within peak':'Motor exceeds peak')+' / '+(s.gearboxPass===null?'Gearbox unassessed':s.gearboxPass?'within momentary':'exceeds momentary'),'Endpoint-work comparison, not hardware qualification']
    ],'Selected component capacity')}<p>Candidate cogging uses the saved enabled passive motor’s amplitude/phase/period count at candidate N. Disabled passives stay zero. Forward efficiency ${s.forwardEfficiency===null?'unassessed':fmt(s.forwardEfficiency*100)+'%'} receives no braking/backdrive credit. Controller, regeneration/DC bus, thermal duration and mechanical fit are unassessed.</p>`;
  }
  function samples(z){
    const curve=z.curve.map(r=>[fmt(r.heightMm),fmt(r.jointTorqueNm),fmt(r.shaftTorqueNm),fmt(r.netMotorWorkJ)]),stroke=z.stroke.map(r=>[fmt(r.hipAngleDeg),fmt(r.wheelCxMm),fmt(r.horizontalWheelDisplacementMm),fmt(r.hipHeightMm),fmt(r.underbodyClearanceMm),fmt(r.motorWorkJ),fmt(r.gravityDeltaJ),fmt(r.springDeltaJ),fmt(r.coggingDeltaJ),fmt(r.kineticBudgetJ)]);
    return `<details><summary>All ${z.curve.length} height samples & ${z.stroke.length} stroke samples</summary><h4>Height curve · endpoint-work screening</h4>${table(['Height · mm','Joint · N·m','Shaft · N·m','Signed demand · J'],curve,'Height torque curve samples')}<h4>Full stroke · signed potential changes from start</h4>${table(['Hip · °','Wheel C_x · mm','Wheel Δx from start · mm','Hip h · mm','Clearance · mm','Motor work · J','ΔUg · J','ΔUs · J','ΔUc · J','K_budget · J'],stroke,'Full stroke energy samples')}</details>`;
  }
  function render(z){
    const jump=z.kind==='jump',scope=(jump?'Ideal jump endpoint estimate':'Initial-arrest landing endpoint screen')+' · '+z.massModel,output=root.querySelector('[data-energy-output]'),primary=root.querySelector('[data-energy-primary]');
    KinefoldPlotly.purge(primary);KinefoldPlotly.purge(output);chartKey='';root.querySelector('[data-energy-announcement]').textContent=(jump?'Jump':'Landing')+' endpoint estimate: '+fmt(z.requiredJointNm)+' joint N·m / '+fmt(z.requiredShaftNm)+' shaft N·m. Updated instantly.';
    primary.innerHTML=`<article class="energy-chart-card"><h4>${jump?'Jump rise':'Fall distance'} → constant torque</h4><p>Joint and shaft magnitudes share units; capacity lines use the same torque side.</p><div data-energy-chart="torque" aria-label="Height versus required torque"></div></article><section class="energy-summary"><span class="eyebrow">${scope.toUpperCase()}</span><div class="solver-readouts">${card('Required constant JOINT torque magnitude',z.requiredJointNm,'N·m')}${card('Required SHAFT magnitude · N='+fmt(z.gearRatio),z.requiredShaftNm,'N·m')}${card(jump?'Target rise ABOVE TAKEOFF':'Drop before first contact',z.selectedHeightMm,'mm')}${card(jump?'Chassis rise during stance':'Clearance at arrest endpoint',jump?z.stanceRiseMm:z.endClearanceMm,'mm')}</div><p class="notice ${z.sampledNegativeInteriorCount||z.boundaryOnly?'error':''}"><strong>${esc(z.pathWarning)}</strong> ${z.boundaryOnly?'Endpoint reaches the mechanical stop; this is not stop avoidance.':''} ${!jump?'Limiter: '+esc(z.limiter)+'.':''}</p><p>${z.workJ<0?(jump?'Signed endpoint demand is negative. Zero drive magnitude leaves a positive endpoint kinetic surplus; the selected apex is not established. ':'Signed endpoint demand is negative. Zero braking magnitude leaves a negative endpoint kinetic budget; earlier arrest/reversal may occur, so this endpoint is not reached. '):''}${z.screening&&!z.screening.gearboxAssessed?'Gearbox capacity is unassessed.':z.passes?'Available torque meets this endpoint-work number.':'Available torque is below this endpoint-work number.'} No peak torque, guaranteed takeoff, impact survival or post-arrest stability is implied.</p><div class="energy-signed-readouts">${card('Signed motor work demand',z.workJ,'J')}${card('Endpoint kinetic budget',z.endpointKineticBudgetJ,'J')}</div></section>`;
    output.innerHTML=`<section class="energy-plots-section"><div class="energy-plot-heading"><div><h3>Energy terms, stroke & geometry</h3><p>Parametric calculations and stroke samples; these are not integrated trajectories.</p></div><div class="energy-range">${field('data-energy-range','heightMinMm','Plot height minimum','mm',0,4999)}${field('data-energy-range','heightMaxMm','Plot height maximum','mm',1,5000)}</div></div><p data-energy-range-error role="status"></p><div class="energy-chart-grid"><article class="energy-chart-card"><h4>Height → endpoint energy terms</h4><p>Signed motor work demand and individual terms; constant geometry is held fixed.</p><div data-energy-chart="height-energy" aria-label="Height versus energy terms"></div></article><article class="energy-chart-card"><h4>Full stroke → accumulated work & kinetic budget</h4><p>Potential changes are signed from start. Negative K_budget is retained and flagged.</p><div data-energy-chart="stroke" aria-label="Full stroke signed energy budget"></div></article><article class="energy-chart-card"><h4>Hip angle → height & clearance</h4><p>Wheel height stays r_w on a stationary horizontal floor; wheel x motion is allowed. Chassis translates vertically at fixed mounting pitch α. Signed wheel travel is tabulated below.</p><div data-energy-chart="geometry" aria-label="Hip angle versus geometry"></div></article></div></section>
      <section class="energy-input-card" data-energy-equations tabindex="-1"><h3>Principles · complete live equation & value table</h3><p class="energy-equation"><b>${jump?'τ_joint = max[0, (ΣmᵢgΔzᵢ + Mflight gH − R_s − R_c) / Δq]':'τ_joint = max[0, (Mdrop gH − ΣmᵢgΔzᵢ − ΔUs − ΔUc) / Δq]'}</b><br>h(q, α) = r_w − [−sin(α) P_u(q) + cos(α) P_v(q)]<br>τ_shaft = τ_joint / N · generalized joint command = −τ_joint<br>K_budget(q) = K₀ + W_motor(q) − ΔU_g(q) − ΔU_s(q) − ΔU_c(q)</p>${equations(z)}<p>q is the saved hip coordinate θ₂; P_u and P_v are the retained VSL source local wheel-centre coordinates (distinct from the static rim-load point P); C_z is wheel position relative to hip A; h is hip height above floor; d is the fixed VERTICAL underside offset below A; it is not a rotated chassis shape. All energy terms are J, angles in work equations are radians. R=U_start−U_end is released energy; ΔU=U_end−U_start is stored energy. A positive motor-work value adds energy; a negative value absorbs it.</p><p>Spring potential is the exact saved finite-idler law. Conservative motor cogging is U_c(q)=A_c/p × cos(pNq+φ), with q,φ in radians, and is zero when the physical passive motor is disabled. Relative joint/rotor rates are assumed zero at the compared endpoints, with a fixed pose during flight. Rotational inertias therefore add no endpoint work here. Retained wheel spin, takeoff/stop redistribution losses, transient inertia and viscous/Coulomb friction require dynamics. No friction dissipation is credited.</p></section>
      <section class="energy-input-card"><h3>Capacity & assumptions</h3>${screening(z)}${!jump?`<p>At the selected endpoint, manual/candidate capacity gives raw drop bound <b>${fmt(z.capacityRawMm)} mm</b>. ${z.capacityRawMm<0?'Negative capacity means even zero-height endpoint demand exceeds available work.':'This is a sufficient endpoint-work bound, not a certified maximum over interior barriers.'}</p>`:''}<p><b>${esc(z.assumptions)}</b></p><p>The checkbox includes or ignores saved upper/lower-link and compound-pulley masses in this calculator only. Uniform-link COMs are the link midpoints; the compound mass is at knee B. Their actual rotated world heights determine gravity work. Jump flight includes all selected masses plus wheel m₆; landing retains chassis plus selected link/compound fall energy and omits wheel impact energy. Saved mechanism and dynamic masses are unchanged. Monotonic world-height travel on a nonsingular straight branch is required; fixed tilted guides are supported through the full rotated geometry. Slack cable, curved/reversing travel and additional prescribed wheel loads are rejected. Changing α does not retune the chassis-local spring or multiply spring work by cos(α). A finite sample has no proof of continuous feasibility.</p></section>
      <section class="energy-input-card"><h3>Calculation data & app-folder exports</h3><div class="design-actions"><button data-energy-export="json">Export complete calculation JSON</button><button data-energy-export="curve">Height curve CSV</button><button data-energy-export="stroke">Full stroke CSV</button></div><p>JSON includes the captured design, all samples and signed terms. CSV files contain every curve/stroke column with units in field names; files are saved to this app’s exports folder.</p>${samples(z)}</section>`;
    root.querySelector('[data-energy-range-error]').textContent=z.selectedHeightMm<plotRange.heightMinMm||z.selectedHeightMm>plotRange.heightMaxMm?'Selected target lies outside the displayed height range; widen it to view the target marker.':'';
    for(const el of root.querySelectorAll('[data-energy-range]')){el.value=plotRange[el.dataset.energyRange];el.onchange=()=>{const fields=[...root.querySelectorAll('[data-energy-range]')],next=Object.fromEntries(fields.map(f=>[f.dataset.energyRange,f.value===''?NaN:Number(f.value)]));try{A.workspace(project,kind,calculationOptions(next));plotRange=next;plotRanges[kind]=next;lastKey='';update(project);}catch(error){root.querySelector('[data-energy-range-error]').textContent=error.message;for(const f of fields)f.setAttribute('aria-invalid','true');}};}
    for(const b of root.querySelectorAll('[data-energy-export]'))b.onclick=()=>exportData(b.dataset.energyExport);
  }
  function charts(){
    if(!result||!root||root.hidden)return;
    if(chartKey===lastKey){KinefoldPlotly.resizeAll(root);return;}
    chartKey=lastKey;const z=result,jump=z.kind==='jump',h=z.curve.map(r=>r.heightMm),q=z.stroke.map(r=>r.hipAngleDeg),colors=['var(--sage)','var(--blue)','var(--red)','var(--amber)','var(--muted)','var(--ink)'];
    const trace=(name,x,y,index,dash)=>({type:'scatter',mode:'lines',name,x,y,line:{color:colors[index%colors.length],width:2,...dash&&{dash}}});
    const torque=[trace('Required JOINT',h,z.curve.map(r=>r.jointTorqueNm),0),trace('Required SHAFT · N='+fmt(z.gearRatio),h,z.curve.map(r=>r.shaftTorqueNm),1),trace(z.screening&&!z.screening.gearboxAssessed?'Joint motor-only bound · gear unassessed':'Available JOINT',h,h.map(()=>z.availableJointNm),0,'dash'),trace('Available SHAFT equivalent',h,h.map(()=>z.availableShaftNm),1,'dash'),{type:'scatter',mode:'markers',name:'Selected joint target',x:[z.selectedHeightMm],y:[z.requiredJointNm],marker:{color:colors[2],size:9}},{type:'scatter',mode:'markers',name:'Selected shaft target',x:[z.selectedHeightMm],y:[z.requiredShaftNm],marker:{color:colors[1],size:8,symbol:'diamond'}}];
    if(z.screening?.nominalNm!==null&&z.screening?.nominalNm!==undefined)torque.push(trace('Gearbox NOMINAL output · reference',h,h.map(()=>z.screening.nominalNm),4,'dot'));
    if(z.screening?.momentaryNm!==null&&z.screening?.momentaryNm!==undefined)torque.push(trace('Gearbox MOMENTARY output',h,h.map(()=>z.screening.momentaryNm),3,'dashdot'));
    const energyTraces=jump?[trace('Flight energy M g H',h,z.curve.map(r=>r.flightEnergyJ),1),trace('Stance gravity increase',h,z.curve.map(r=>r.gravityJ),3),trace('Spring released',h,z.curve.map(r=>r.springReleaseJ),0),trace('Cogging released',h,z.curve.map(r=>r.coggingReleaseJ),4)]:[trace('Fall energy Mdrop g H',h,z.curve.map(r=>r.dropJ),1),trace('Gravity released in compression',h,z.curve.map(r=>r.gravityJ),3),trace('Spring stored ΔUs',h,z.curve.map(r=>-r.springReleaseJ),0),trace('Cogging stored ΔUc',h,z.curve.map(r=>-r.coggingReleaseJ),4)];
    energyTraces.push(trace('Signed net motor work demand',h,z.curve.map(r=>r.netMotorWorkJ),2));
    const stroke=[trace('Motor work · signed',q,z.stroke.map(r=>r.motorWorkJ),0),trace('Gravity change ΔUg',q,z.stroke.map(r=>r.gravityDeltaJ),3),trace('Spring change ΔUs',q,z.stroke.map(r=>r.springDeltaJ),1),trace('Cogging change ΔUc',q,z.stroke.map(r=>r.coggingDeltaJ),4),trace('K_budget · unclipped',q,z.stroke.map(r=>r.kineticBudgetJ),2),trace('Initial K₀',q,q.map(()=>z.initialKineticBudgetJ),5,'dot')];
    const geometry=[trace('Hip height',q,z.stroke.map(r=>r.hipHeightMm),1),trace('Underbody clearance',q,z.stroke.map(r=>r.underbodyClearanceMm),0)];
    if(!jump)geometry.push(trace('Target clearance',q,q.map(()=>z.config.targetClearanceMm),2,'dash'));
    const labels={torque:['Target '+(jump?'rise ABOVE TAKEOFF':'fall distance')+' · mm','Constant torque magnitude · N·m'],'height-energy':['Target height · mm','Endpoint energy · J'],stroke:['Hip angle θ₂ · °','Accumulated work / energy · J'],geometry:['Hip angle θ₂ · °','Height above floor · mm']};
    for(const [name,data]of Object.entries({torque,'height-energy':energyTraces,stroke,geometry})){
      const host=root.querySelector(`[data-energy-chart="${name}"]`),[x,y]=labels[name];
      KinefoldPlotly.react(host,data,{height:410,title:{text:(jump?'Jump':'Landing')+' · α = '+fmt(z.alphaDeg)+'°',font:{size:13},x:.02},margin:{l:76,r:22,t:42,b:145},xaxis:{title:{text:x},...(name==='stroke'||name==='geometry'?{autorange:jump?'reversed':true}:{range:[plotRange.heightMinMm,plotRange.heightMaxMm],autorange:false})},yaxis:{title:{text:y}},legend:{orientation:'h',y:-.27,font:{size:11}}},{key:'energy-'+kind+'-'+name}).catch(error=>{if(host.isConnected)host.textContent='Chart unavailable: '+error.message;});
    }
  }
  async function exportData(format){
    try{const p=S.exportProject(),z=A.workspace(p,kind,calculationOptions(plotRange));if(format==='json')await S.saveArtifact(`kinefold-energy-${kind}.json`,{schema:'kinefold/energy-workspace-v1',projectSnapshot:p,calculation:z});else{const rows=format==='curve'?z.curve:z.stroke,keys=Object.keys(rows[0]);await S.saveArtifact(`kinefold-energy-${kind}-${format}.csv`,keys.join(',')+'\n'+rows.map(r=>keys.map(k=>r[k]??'').join(',')).join('\n'),'text/csv');}}
    catch(error){S.toast('Energy export unavailable: '+error.message);}
  }
  function update(p,force=false){
    if(!root)return;project=p;const e=energy(p),c={...P.caseDefaults,...p.caseConfig},t={...P.torqueTargetDefaults,...p.torqueTargetConfig};
    renderJumpTravel(p);
    root.querySelector('[data-energy-leg-masses]').checked=includeLegMasses;
    root.querySelector('[data-energy-mass-note]').textContent=includeLegMasses?`Included: upper ${fmt(p.params.m2)} kg, lower ${fmt(p.params.m3)} kg, compound ${fmt(p.params.m5)} kg. Ideal endpoint energy; inertia/contact losses require dynamics.`:'Massless approximation: upper/lower links and compound pulley ignored in this calculator only. Saved mechanism and dynamic masses stay unchanged.';
    root.querySelector('[data-energy-alpha]').textContent=`Saved mounting pitch α = ${fmt(p.params.alpha)}° · read from Mechanism studio and included in every world-height/gravity calculation. This is mounting pitch, not terrain slope. Local spring geometry and saved preload/stiffness stay unchanged.`;
    root.querySelector('[data-energy-identity]').textContent=`${p.name} · Chassis m₁ = ${fmt(p.params.m1)} kg per leg · α = ${fmt(p.params.alpha)}° · saved geometry & spring`;
    root.querySelector('[data-energy-identity]').setAttribute('title',`Saved mechanism ${p.id}`);
    root.querySelector('[data-energy-context-values]').textContent=`Chassis m₁ = ${fmt(p.params.m1)} kg per leg · Links m₂ / m₃ = ${fmt(p.params.m2)} / ${fmt(p.params.m3)} kg · Wheel m₆ = ${fmt(p.params.m6)} kg.`;
    root.querySelector('[data-energy-input-heading]').textContent=kind==='jump'?'Jump target':'Landing target';
    root.querySelector('[data-energy-geometry-heading]').textContent='Shared dynamic landing defaults';
    root.querySelector('[data-energy-case="landingOpenFraction"]').closest('label').hidden=false;
    for(const key of ['compressionReserveDeg','targetClearanceMm'])root.querySelector(`[data-energy-key="${key}"]`).closest('label').hidden=kind!=='landing'||!!e.travelRanges?.landing;
    root.querySelector('[data-energy-geometry-note]').textContent='These defaults do not overwrite an explicit Energy travel range. Use Restore case default to follow them again.';
    for(const b of root.querySelectorAll('[data-energy-mode]'))b.setAttribute('aria-pressed',b.dataset.energyMode===kind?'true':'false');
    for(const group of root.querySelectorAll('[data-energy-for]'))group.hidden=group.dataset.energyFor!==kind;
    root.querySelector('[data-energy-two-metre]').hidden=kind!=='landing';
    root.querySelector('[data-energy-datum]').textContent=kind==='jump'?'H is airborne rise above the selected takeoff pose, in addition to the stance rise across the selected band.':'H is wheel-bottom gap before contact. Residual clearance is underside-to-floor distance at first arrest, not the underside offset below A.';
    for(const el of root.querySelectorAll('[data-energy-key]'))el.value=e[el.dataset.energyKey];
    for(const el of root.querySelectorAll('[data-energy-target]'))el.value=t[el.dataset.energyTarget];
    for(const el of root.querySelectorAll('[data-energy-case]'))el.value=c[el.dataset.energyCase]??'';
    const s=e.screening;root.querySelector('[data-energy-motor]').value=s?.motorId??'manual';root.querySelector('[data-energy-gear]').value=s?.gearboxId??'direct';root.querySelector('[data-energy-gear]').disabled=!s;root.querySelector('[data-energy-gear]').closest('label').hidden=!s;
    for(const el of root.querySelectorAll('[data-energy-screen]')){const k=el.dataset.energyScreen;el.value=s?.[k]??(k==='customRatio'?1:'');el.disabled=!s||(k!=='peakShaftNm'&&s.gearboxId!=='custom');el.closest('label').hidden=!s||(k!=='peakShaftNm'&&s.gearboxId!=='custom');}
    root.querySelector('[data-energy-key="torqueLimitNm"]').disabled=!!s;root.querySelector('[data-energy-remove]').disabled=!p.energyConfig;
    const key=JSON.stringify([p.id,p.name,{...p.params,theta2:null},p.motorConfig,c.landingOpenFraction,c.undersideOffsetMm,e,t.jumpHeightMm,kind,plotRange,includeLegMasses]);
    if(!force&&key===lastKey){handoff();charts();return;}lastKey=key;
    try{result=A.workspace(p,kind,calculationOptions(plotRange));render(result);charts();}
    catch(error){result=null;root.querySelector('[data-energy-announcement]').textContent='Energy calculation unavailable: '+error.message;KinefoldPlotly.purge(root.querySelector('[data-energy-primary]'));root.querySelector('[data-energy-primary]').innerHTML=`<p class="notice error"><strong>Energy calculation unavailable.</strong> ${esc(error.message)} Edit the parameters below or the mechanism in Studio.</p>`;KinefoldPlotly.purge(root.querySelector('[data-energy-output]'));root.querySelector('[data-energy-output]').innerHTML=`<p class="notice error"><strong>Energy calculation unavailable.</strong> ${esc(error.message)} Edit the inputs or the mechanism in Studio. No result or capacity claim is displayed for this input.</p>`;}
    handoff();
  }
  window.addEventListener('kinefold-solver-tab',()=>charts());
  return {mount,update,open,command,getState:()=>({kind,result,includeLegMasses,plotRange:{...plotRange},plotRanges:{jump:{...plotRanges.jump},landing:{...plotRanges.landing}}})};
})();
